using System;
class Attr1<T> : Attribute { }
class Attr2<T> : Attribute where T : I1 { }

interface I1
{
    static abstract void M();
}

interface I2 : I1 { }

class C : I1
{
    public static void M() { }
}

[Attr1<I1>]
[Attr2<I1>]
class C1 { }

[Attr1<I2>]
[Attr2<I2>]
class C2 { }

